Lemma geo_1RB0LA_1LC0RD_1RC0LB_1LA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LA_1LC0RD_1RC0LB_1LA1RD) = lift (Cc (Pos.succ p)).
