(** ** The lap *)

Lemma lap_1RB0LA_1LC0RD_1RC0LB_1LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LA_1LC0RD_1RC0LB_1LA1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LA_1LC0RD_1RC0LB_1LA1RD B0_1RB0LA_1LC0RD_1RC0LB_1LA1RD B1_1RB0LA_1LC0RD_1RC0LB_1LA1RD 2 12 p j' [] []).
    + exact run_ovf_1RB0LA_1LC0RD_1RC0LB_1LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LA_1LC0RD_1RC0LB_1LA1RD p j' E).
    + exact (geo_1RB0LA_1LC0RD_1RC0LB_1LA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0LA_1LC0RD_1RC0LB_1LA1RD : stepn tmm_1RB0LA_1LC0RD_1RC0LB_1LA1RD 17 InitES = Some (lift (Cc 1)).
