  apply (lap_qh_stage tmm_1RB0LA_1LC0RD_1RC0LB_1LA1RD pins_1RB0LA_1LC0RD_1RC0LB_1LA1RD Cc 1 17 32779478).
  - exact bootq_1RB0LA_1LC0RD_1RC0LB_1LA1RD.
  - intros p _. apply lap_1RB0LA_1LC0RD_1RC0LB_1LA1RD.
  - intros t Ht p _. apply fire_1RB0LA_1LC0RD_1RC0LB_1LA1RD. exact Ht.
  - exact wit_1RB0LA_1LC0RD_1RC0LB_1LA1RD.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_1RB0LA_1LC0RD_1RC0LB_1LA1RD : NonHalt tm_1RB0LA_1LC0RD_1RC0LB_1LA1RD /\ QHBoundTr 32779478 tm_1RB0LA_1LC0RD_1RC0LB_1LA1RD /\ QuasiHaltsTr tm_1RB0LA_1LC0RD_1RC0LB_1LA1RD.
