    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_0RC0LA_1RD1RC_1LD1LB B0_1RB0LB_0RC0LA_1RD1RC_1LD1LB B1_1RB0LB_0RC0LA_1RD1RC_1LD1LB 4 8 p j' [] []).
