  split; [lia|]. split; [| exact (gen_1RB0LB_0RC1LA_1LB1RD_1LA1RC v i q0 E)].
  rewrite (gsn_1RB0LB_0RC1LA_1LB1RD_1LA1RC v i q0 E).
  exact (srun_sound tm false true chn_1RB0LB_0RC1LA_1LB1RD_1LA1RC AI0_1RB0LB_0RC1LA_1LB1RD_1LA1RC AI1_1RB0LB_0RC1LA_1LB1RD_1LA1RC 4 8
           run_inner_1RB0LB_0RC1LA_1LB1RD_1LA1RC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
