(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LB_1LC0LD_0RD0LC_1RA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB0LB_1LC0LD_0RD0LC_1RA1RD.
