(** ** The lap *)

Lemma lap_1RB0LB_1LC0LD_0RD0LC_1RA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
