    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_1LC0LD_0RD0LC_1RA1RD B0_1RB0LB_1LC0LD_0RD0LC_1RA1RD B1_1RB0LB_1LC0LD_0RD0LC_1RA1RD 6 12 p j' [] []).
    + exact run_ovf_1RB0LB_1LC0LD_0RD0LC_1RA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_1LC0LD_0RD0LC_1RA1RD p j' E).
    + exact (geo_1RB0LB_1LC0LD_0RD0LC_1RA1RD p j' E).
    + lia.
