(** ** The lap *)

Lemma lap_1RB0LB_1LC1RA_0RB1LD_0LC0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
