  - destruct (lapi_1RB0LB_1LC1RA_0RB1LD_0LC0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_1LC1RA_0RB1LD_0LC0LC B0_1RB0LB_1LC1RA_0RB1LD_0LC0LC B1_1RB0LB_1LC1RA_0RB1LD_0LC0LC 6 14 p j' [] []).
    + exact run_ovf_1RB0LB_1LC1RA_0RB1LD_0LC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_1LC1RA_0RB1LD_0LC0LC p j' E).
    + exact (geo_1RB0LB_1LC1RA_0RB1LD_0LC0LC p j' E).
    + lia.
Qed.

