    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_1LC1RA_0RD0LC_1LB0RB B0_1RB0LB_1LC1RA_0RD0LC_1LB0RB B1_1RB0LB_1LC1RA_0RD0LC_1LB0RB 4 14 p j' [] []).
    + exact run_ovf_1RB0LB_1LC1RA_0RD0LC_1LB0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_1LC1RA_0RD0LC_1LB0RB p j' E).
    + exact (geo_1RB0LB_1LC1RA_0RD0LC_1LB0RB p j' E).
    + lia.
