      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LB_1LC1RD_0RD0LC_1RA0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LB_1LC1RD_0RD0LC_1RA0LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
  - (* D0 *)
